CREATE COLUMN TABLE "TEST_AP"."RTM1" ("LineNum" INTEGER CS_INT NOT NULL , "TransId" INTEGER CS_INT NOT NULL , "JdtLine" INTEGER CS_INT DEFAULT 0 NOT NULL , "IsSysCurr" NVARCHAR(1) DEFAULT 'N' NOT NULL , "AcctCode" NVARCHAR(15), "Balance" DECIMAL(21,6) CS_FIXED, "FrnBlnc" DECIMAL(21,6) CS_FIXED, "Valid" NVARCHAR(1) DEFAULT 'Y', "RevalRate" DECIMAL(21,6) CS_FIXED, "Delta" DECIMAL(21,6) CS_FIXED, "FCCurrency" NVARCHAR(3), "JdtAcctCod" NVARCHAR(15), "BaseRef" NVARCHAR(11), "JdtType" NVARCHAR(1) DEFAULT 'U', "RefDate" LONGDATE CS_LONGDATE, "DueDate" LONGDATE CS_LONGDATE, "TaxDate" LONGDATE CS_LONGDATE, "BPLId" INTEGER CS_INT, "CntBlnc" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("LineNum", "TransId", "JdtLine", "IsSysCurr")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE INDEX "RTM1_SYS_CURR" ON "TEST_AP"."RTM1" ( "IsSysCurr" ASC )